1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! `RECEIVE` — synchronous receive.
4	//!
5	//! Translation of MINIX 3 `kernel/proc.c:977 mini_receive()`. Searches in
6	//! order: pending notifications (synthesized on the fly from the caller's
7	//! `priv.notify_pending` bitmap), then queued senders in `caller_q`. If
8	//! nothing matches, the caller blocks with `RTS_RECEIVING` and records
9	//! the source filter and user-buffer VA so a later [`mini_send`] can
10	//! deposit the message and unblock us.
11	
12	use core::sync::atomic::Ordering;
13	
14	use minixrs_kernel_shared::ProcNr;
15	use minixrs_kernel_shared::com::NR_SYS_PROCS;
16	use minixrs_kernel_shared::endpoint::{ANY, Endpoint};
17	use minixrs_kernel_shared::error::{EBADSRCDST, ELOCKED, ENOTREADY, OK};
18	use minixrs_kernel_shared::ipc_const::RECEIVE;
19	
20	use crate::ipc::deadlock::deadlock_check;
21	use crate::ipc::notify::build_notify_message;
22	use crate::proc::flags::{MF_DELIVERMSG, MF_REPLY_PEND, RTS_RECEIVING, RTS_SENDING};
23	use crate::proc::priv_struct::IPC_MAP_CHUNKS;
24	use crate::proc::table::{N_PROC_SLOTS, okendpt, proc_index};
25	use crate::proc::{Priv, Proc, sched};
26	
27	/// Blocking discipline for [`mini_receive`].
28	#[derive(Copy, Clone, Eq, PartialEq, Debug)]
29	pub enum RecvFlags {
30	    /// `RECEIVE` — block if no matching message is queued.
31	    Blocking,
32	    /// Non-blocking (no IPC primitive exposes this today, but the dispatch
33	    /// path passes it from the `RECEIVE` half of a SENDREC; symmetric to
34	    /// [`super::send::SendFlags::NonBlocking`]).
35	    #[allow(dead_code)]
36	    NonBlocking,
37	}
38	
39	/// `RECEIVE` primitive.
40	pub fn mini_receive(
41	    proc_table: &mut [Proc; N_PROC_SLOTS],
42	    priv_table: &mut [Priv; NR_SYS_PROCS],
43	    caller_nr: ProcNr,
44	    src_e: Endpoint,
45	    user_msg_va: u64,
46	    flags: RecvFlags,
47	) -> i32 {
48	    let Some(caller_idx) = proc_index(caller_nr) else {
49	        return EBADSRCDST;
50	    };
51	
52	    // Slots recycle as of slice 4.6: a specific source filter must pass
53	    // okendpt so receiving from a dead endpoint fails with EDEADSRCDST
54	    // instead of blocking forever (MINIX 3 proc.c:999).
55	    if src_e != ANY
56	        && let Err(e) = okendpt(proc_table, src_e)
57	    {
58	        return e;
59	    }
60	
61	    // Record buffer VA up-front. Even if we block here, a later deferred
62	    // SEND will find this and deposit the message at the right place when
63	    // the flush path runs.
64	    proc_table[caller_idx].deliver_msg_vir = user_msg_va;
65	
66	    // SENDREC mid-flight: SEND half blocked, RECEIVE half just kicked in.
67	    // Skip pending-message checks and proceed straight to "block on
68	    // receive". MINIX 3 proc.c:1010.
69	    let caller_rts = proc_table[caller_idx].rts_flags.load(Ordering::Relaxed);
70	    let in_mid_sendrec = caller_rts & RTS_SENDING != 0;
71	
72	    if !in_mid_sendrec {
73	        // 1. Pending notification?
74	        if let Some(sender_e) = take_pending_notification(proc_table, priv_table, caller_idx, src_e)
75	        {
76	            let caller = &mut proc_table[caller_idx];
77	            build_notify_message(caller, sender_e);
78	            caller.misc_flags |= MF_DELIVERMSG;
79	            return OK;
80	        }
81	
82	        // 2. (Skip pending async — `mini_senda` is an ENOSYS stub.)
83	
84	        // 3. Walk caller_q for a sender matching src_e (or ANY).
85	        if let Some(matched) = walk_caller_q(proc_table, caller_idx, src_e) {
86	            return matched;
87	        }
88	    }
89	
90	    // Nothing to deliver.
91	    if flags == RecvFlags::NonBlocking {
92	        return ENOTREADY;
93	    }
94	
95	    if deadlock_check(&*proc_table, RECEIVE, caller_nr, src_e) {
96	        return ELOCKED;
97	    }
98	
99	    let caller = &mut proc_table[caller_idx];
100	    caller.getfrom_e = src_e;
101	    // SAFETY: single-threaded SVC invariant; no other borrow into
102	    // `proc_table` is live.
103	    unsafe { sched::rts_set(caller, RTS_RECEIVING) };
104	    OK
105	}
106	
107	/// Look for the first pending notification matching `src_e` (or any, if
108	/// `src_e == ANY`) in `caller`'s `notify_pending` bitmap. Returns the
109	/// sender's endpoint and clears the bit on success.
110	fn take_pending_notification(
111	    proc_table: &[Proc; N_PROC_SLOTS],
112	    priv_table: &mut [Priv; NR_SYS_PROCS],
113	    caller_idx: usize,
114	    src_e: Endpoint,
115	) -> Option<Endpoint> {
116	    let caller_priv_id = proc_table[caller_idx].priv_id?;
117	    let caller_priv_idx = caller_priv_id.as_usize();
118	
119	    // Snapshot the caller's notify_pending bitmap so the lookup loop can
120	    // read other priv_table slots without holding a mutable borrow.
121	    let pending_snapshot: [u32; IPC_MAP_CHUNKS] = priv_table[caller_priv_idx].notify_pending;
122	
123	    // TODO(slice 2.6+): when src_e != ANY, resolve priv_id directly
124	    // (endpoint → proc_index → priv_id) and test that single bit, rather
125	    // than scanning the whole bitmap. Current map is 64 bits so the walk
126	    // is fine, but cost grows with NR_SYS_PROCS.
127	    for (chunk_idx, &chunk_val) in pending_snapshot.iter().enumerate() {
128	        let mut chunk = chunk_val;
129	        while chunk != 0 {
130	            let bit = chunk.trailing_zeros() as usize;
131	            let sender_priv_idx = chunk_idx * 32 + bit;
132	            if sender_priv_idx < NR_SYS_PROCS
133	                && let Some(sender_nr) = priv_table[sender_priv_idx].proc_nr
134	                && let Some(sender_idx) = proc_index(sender_nr)
135	            {
136	                let sender_e = proc_table[sender_idx].endpoint;
137	                if src_e == ANY || src_e == sender_e {
138	                    // Clear bit and return.
139	                    priv_table[caller_priv_idx].notify_pending[chunk_idx] &= !(1u32 << bit);
140	                    return Some(sender_e);
141	                }
142	            }
143	            chunk &= chunk - 1; // pop lowest set bit and try next
144	        }
145	    }
146	    None
147	}
148	
149	/// Walk `caller_q` rooted at `proc_table[caller_idx]` for the first sender
150	/// matching `src_e` (or any, if `src_e == ANY`). On match, deliver the
151	/// sender's `send_msg` into the caller's `deliver_msg`, set `MF_DELIVERMSG`,
152	/// clear `MF_REPLY_PEND` (SENDREC completion), unblock the sender, splice
153	/// it out of the queue, and return `Some(OK)`. Returns `None` if nothing
154	/// matches.
155	fn walk_caller_q(
156	    proc_table: &mut [Proc; N_PROC_SLOTS],
157	    caller_idx: usize,
158	    src_e: Endpoint,
159	) -> Option<i32> {
160	    let mut prev: Option<usize> = None;
161	    let mut cur = proc_table[caller_idx].caller_q;
162	
163	    while let Some(sender_nr) = cur {
164	        let sender_idx = proc_index(sender_nr).expect("caller_q entry in range");
165	        let sender_e = proc_table[sender_idx].endpoint;
166	        let next = proc_table[sender_idx].q_link;
167	
168	        if src_e == ANY || src_e == sender_e {
169	            // Deliver: copy the buffered message into the caller's
170	            // deliver_msg (m_source was already stamped by mini_send).
171	            let msg = proc_table[sender_idx].send_msg;
172	            let caller = &mut proc_table[caller_idx];
173	            caller.deliver_msg = msg;
174	            caller.misc_flags |= MF_DELIVERMSG;
175	            caller.misc_flags &= !MF_REPLY_PEND;
176	
177	            // Splice sender out of the queue.
178	            match prev {
179	                None => proc_table[caller_idx].caller_q = next,
180	                Some(p_idx) => proc_table[p_idx].q_link = next,
181	            }
182	            {
183	                let sender = &mut proc_table[sender_idx];
184	                sender.q_link = None;
185	                // SAFETY: single-threaded SVC invariant.
186	                unsafe { sched::rts_unset(sender, RTS_SENDING) };
187	            }
188	            return Some(OK);
189	        }
190	
191	        prev = Some(sender_idx);
192	        cur = next;
193	    }

